import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, vec2, dot, sin, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const group = new Group();
  group.name = 'editorial-oversized-type';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const bg = new Color(colors.background ?? '#0b0b10');
  const surf = new Color(colors.surface ?? '#14141a');
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');

  // --- Backdrop: full-bleed editorial plate 7 x 5.5, vertical engineered gradient + grain
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.toneMapped = false;
  const v = uv();
  const grad = mix(vec3(bg.r, bg.g, bg.b), vec3(surf.r, surf.g, surf.b), v.y);
  const grain = fract(sin(dot(v.mul(1000.0), vec2(12.9898, 78.233))).mul(43758.5453));
  backdropMat.colorNode = grad.add(grain.mul(0.015));
  const backdrop = new Mesh(new PlaneGeometry(7, 5.5), backdropMat);
  backdrop.position.set(0, 0, 0);
  group.add(backdrop);

  // --- Text content (bridging idiom)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findByRole = (role) => items.find((i) => i.role === role);
  const x = -3.1;
  const blocks = [];

  function registerBlock(wrap, baseY, mats) {
    wrap.position.set(x, baseY + 0.4, 0);
    group.add(wrap);
    blocks.push({ wrap, mats, baseY });
  }

  function collectMats(obj) {
    const mats = [];
    obj.traverse((o) => {
      if (o.material) {
        o.material.transparent = true;
        o.material.opacity = 0;
        mats.push(o.material);
      }
    });
    return mats;
  }

  // Kicker — "NOVA ATELIER / JOURNAL"
  const kicker = findByRole('kicker');
  if (kicker) {
    const t = ctx.fontAtlas.createText(kicker.text, {
      fontSize: 18,
      color: paper.getHex(),
      align: 'left',
      letterSpacingPx: 2,
    });
    t.position.set(0, 0, 0.05);
    const wrap = new Group();
    wrap.add(t);
    registerBlock(wrap, 1.7, collectMats(t));
  }

  // Hero — two stacked lines with letterpress shadow edge
  const heroItems = items.filter((i) => i.role === 'hero');
  const heroYs = [0.9, 0.25];
  heroItems.forEach((item, idx) => {
    const y = heroYs[idx] ?? 0;
    const wrap = new Group();
    const shadow = ctx.fontAtlas.createText(item.text, {
      fontSize: 124,
      color: ink.getHex(),
      align: 'left',
      letterSpacingPx: -2,
    });
    shadow.position.set(0, 0, 0.03);
    const main = ctx.fontAtlas.createText(item.text, {
      fontSize: 124,
      color: paper.getHex(),
      align: 'left',
      letterSpacingPx: -2,
    });
    main.position.set(0, 0, 0.05);
    wrap.add(shadow);
    wrap.add(main);
    registerBlock(wrap, y, collectMats(wrap));
  });

  // Body paragraph
  const body = findByRole('body');
  if (body) {
    const t = ctx.fontAtlas.createText(body.text, {
      fontSize: 26,
      color: paper.getHex(),
      align: 'left',
      maxWidthPx: 900,
    });
    t.position.set(0, 0, 0.05);
    const wrap = new Group();
    wrap.add(t);
    registerBlock(wrap, -0.8, collectMats(t));
  }

  // Caption
  const caption = findByRole('caption');
  if (caption) {
    const t = ctx.fontAtlas.createText(caption.text, {
      fontSize: 18,
      color: paper.getHex(),
      align: 'left',
      letterSpacingPx: 1.4,
    });
    t.position.set(0, 0, 0.05);
    const wrap = new Group();
    wrap.add(t);
    registerBlock(wrap, -1.9, collectMats(t));
  }

  // --- Accent underline rule — 2.2 x 0.05, emissive signal red, draws from left
  const ruleMat = new MeshStandardNodeMaterial();
  ruleMat.color = new Color(0x000000);
  ruleMat.emissive = accent.clone();
  ruleMat.emissiveIntensity = 1.2;
  ruleMat.toneMapped = false;
  const ruleGeo = new PlaneGeometry(2.2, 0.05);
  ruleGeo.translate(2.2 / 2, 0, 0); // anchor at left edge for scaleX growth
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(x, -0.15, 0.04);
  rule.scale.x = 0;
  group.add(rule);

  // --- GSAP entrance: rise-in per block, 80ms stagger; rule draws after hero lands
  const tl = gsap.timeline();
  const easeRise = 'cubic-bezier(0.215,0.61,0.355,1)';
  const easeRule = 'cubic-bezier(0.25,0.46,0.45,0.94)';

  blocks.forEach((b, i) => {
    tl.to(
      b.wrap.position,
      { y: b.baseY, duration: 0.7, ease: easeRise },
      i * 0.08,
    );
    tl.to(
      b.mats,
      { opacity: 1, duration: 0.7, ease: easeRise },
      i * 0.08,
    );
  });

  const ruleStart = (blocks.length - 1) * 0.08 + 0.7;
  tl.to(
    rule.scale,
    { x: 1, duration: 0.5, ease: easeRule },
    ruleStart,
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    group.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
        else o.material.dispose();
      }
    });
  };

  return group;
}
